import json

def solve():
    curr_x = int(input_data['start_x'])
    curr_y = int(input_data['start_y'])
    target_x = int(input_data['target_x'])
    target_y = int(input_data['target_y'])
    map_id = str(input_data['map_id'])

    passable_tiles = set()

    if '82' in map_id: # Rock Tunnel 1F
        # 1. Western Starting Chamber (Rows 4-7, Columns 13-28)
        for y in range(4, 8):
            for x in range(13, 29):
                passable_tiles.add((x, y))

        # 2. Eastern Corridor (Rows 10-13, Columns 20-33)
        for y in range(10, 14):
            for x in range(20, 34):
                passable_tiles.add((x, y))

        # 3. Verified trail to Pokémaniac at (22, 8)
        passable_tiles.add((22, 8))
        passable_tiles.add((22, 9))

        # 4. Route 10 Exit/Entrance Warp
        passable_tiles.add((15, 3))
        passable_tiles.add((15, 4))

        # 5. Newly Discovered 1F Isolated Section: Columns 2-10, Rows 2-11
        for y in range(2, 12):
            for x in range(2, 11):
                # Exclude the rock wall block on Rows 10-11 at Columns 6-7
                if y in (10, 11) and x in (6, 7):
                    continue
                passable_tiles.add((x, y))

        # Ladder at (5, 3)
        passable_tiles.add((5, 3))

    else: # Rock Tunnel B1F (0_232)
        # 1. Starting Chamber (Rows 22-25, Columns 28-37)
        for y in range(22, 26):
            for x in range(28, 38):
                passable_tiles.add((x, y))

        # 2. Starting Chamber South expansion (Rows 26-29, Columns 28-34)
        for y in range(26, 30):
            for x in range(28, 35):
                passable_tiles.add((x, y))

        # 3. Row 30 passable area (Row 30, Columns 28-34)
        for x in range(28, 35):
            passable_tiles.add((x, 30))

        # 4. Row 31 southern corridor (Row 31, Columns 17-37)
        for x in range(17, 38):
            passable_tiles.add((x, 31))

        # 5. Column 17 vertical corridor (Rows 22-31, Column 17)
        for y in range(22, 32):
            passable_tiles.add((17, y))

        # 6. Row 22 horizontal corridor (Row 22, Columns 17-24)
        for x in range(17, 25):
            passable_tiles.add((x, 22))

        # 7. Column 24 vertical corridor (Rows 19-22, Column 24)
        for y in range(19, 23):
            passable_tiles.add((24, y))

        # 8. Row 19 upper horizontal corridor (Row 19, Columns 24-37)
        for x in range(24, 38):
            passable_tiles.add((x, 19))

        # 9. Column 37 eastern vertical corridor (Rows 2-19, Column 37)
        for y in range(2, 20):
            passable_tiles.add((37, y))

        # 10. Upper horizontal bypass extension (Rows 1-5, Columns 33-37)
        for y in range(1, 6):
            for x in range(33, 38):
                passable_tiles.add((x, y))

        # Ladder A tile itself
        passable_tiles.add((33, 25))

    # Include start/target tiles to ensure search works
    passable_tiles.add((curr_x, curr_y))
    passable_tiles.add((target_x, target_y))

    # BFS to find the shortest path
    queue = [[(curr_x, curr_y)]]
    visited = {(curr_x, curr_y)}

    path_found = None
    while queue:
        path = queue.pop(0)
        x, y = path[-1]

        if (x, y) == (target_x, target_y):
            path_found = path
            break

        for dx, dy, move in [(-1, 0, 'Left'), (1, 0, 'Right'), (0, -1, 'Up'), (0, 1, 'Down')]:
            nx, ny = x + dx, y + dy
            if (nx, ny) in passable_tiles and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(path + [(nx, ny)])

    if not path_found:
        print(json.dumps([]))
        return

    # Convert path to buttons
    buttons = []
    for i in range(len(path_found) - 1):
        x1, y1 = path_found[i]
        x2, y2 = path_found[i+1]
        if x2 > x1:
            buttons.append('Right')
        elif x2 < x1:
            buttons.append('Left')
        elif y2 > y1:
            buttons.append('Down')
        elif y2 < y1:
            buttons.append('Up')

    print(json.dumps(buttons))

solve()
